// ValidVerifier reports whether s satisfies RFC 7636 §4.1's syntactic
// definition of a code_verifier:
//
//	code_verifier = 43*128unreserved
//	unreserved    = ALPHA / DIGIT / "-" / "." / "_" / "~"
//
// It checks both the [43,128] length bounds and the unreserved character
// set, so callers can reject malformed verifiers before hashing them.
func ValidVerifier(s string) bool {
	if len(s) < VerifierMinLen || len(s) > VerifierMaxLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		if !isUnreserved(s[i]) {
			return false
		}
	}
	return true
}

// isUnreserved reports whether b is a member of RFC 3986 / RFC 7636
// "unreserved" (ALPHA / DIGIT / "-" / "." / "_" / "~"). The verifier is
// ASCII-only by construction, so a byte-wise check is exact.
func isUnreserved(b byte) bool {
	switch {
	case b >= 'A' && b <= 'Z':
		return true
	case b >= 'a' && b <= 'z':
		return true
	case b >= '0' && b <= '9':
		return true
	case b == '-' || b == '.' || b == '_' || b == '~':
		return true
	default:
		return false
	}
}

